/**
 * Pure layout for the CompareBadge diagram family — two near-black plate
 * columns flanking a central orange badge (user8 seg12, 134s–139s).
 *
 * Every constant below was measured on the seg12 settled reference frame
 * (2560×1440, `/home/user/work/user8-analysis/seg12_134s-139s/settled.png`,
 * report.json `seg12_134s-139s`); the settled frame maps 1:1 onto the
 * 1920×1080 stage (the seg12 recording is a full-frame capture — its title
 * band y 0.0965–0.1493 matches the deck chrome convention exactly, so no
 * crop-offset fit is needed):
 *
 * - Each column is TWO stacked near-black plates, not one slab — the settled
 *   frame reads plate luma (6–40, V-3: `#12131a` median, slightly blue-tinted,
 *   NOT gray) framed by a ~2px lighter border line (median rgb(44,45,53) ≈
 *   `#2b2d35`, luma ≈ 46) over y 574–750 and 986–1163, with a pure-black slot
 *   between them where the badge sits. Columns are x 310–978 (left) and
 *   x 1582–2248 (right) — 668/666px wide, 310px margins, 604px slot (settled
 *   scanlines this session; the earlier 314/664 read stopped at the fill,
 *   missing the border line).
 * - The badge is a rounded-square orange core (settled orange scanline box
 *   x 1155–1406, y 714–961 → 251×247px, corner r≈64 native — the top edge
 *   cuts ~47px in by dy=3, r≈64 fits rows 716/718/722 cleanly) sitting on a
 *   dark red-brown radial glow: sampled along +x from the core center,
 *   rgb(64,21,4) ≈ `#401504` at the core edge (r≈128) fading through
 *   rgb(24,9,1) at r≈150 and rgb(7,0,0) at r≈180 — a soft gradient, NOT a
 *   hard-edged circle. The glow is modeled as a radial gradient of the settled
 *   rim sample reaching r≈190 native (HALO_PEAK_FRAC = core edge / glow radius).
 * - THREE dim-orange leader lines (`#bb5323` ~3px strokes) connect the badge
 *   to the plates; the settled frame shows no lower-right stroke. Endpoints
 *   read off the leader ASCII map (ds=8, this session): UL (995,663)→(1153,760)
 *   ends at the core's left edge, UR (1578,660)→(1408,766) starts 4px off the
 *   right plate's inner edge, LL (995,1066)→(1150,942) ends at the core's
 *   bottom-left corner. UL/LL outer tips hover 17px right of the left plates'
 *   inner edge; the lines are not 4-fold symmetric — pinned as measured.
 * - The core's fill is the settled median rgb(248, 87, 33) — exactly the
 *   deck's orange `#f85721` (the research brief's exact sample). Its dark
 *   glyph zone reads x 1228–1334, y 782–898 (dark-inside-orange scan).
 * - Each plate carries an icon glyph box + two text rows: a bright white
 *   headline (38px cap band native, tops 621/1035) and a dim gray detail
 *   line (17.5px x-height band, tops 691/1104). Line ink starts at x 468
 *   (left plates) / x 1736 (right plates). Line TEXT is content — it travels
 *   with the slide as `BadgeRowContent`, with per-run `brightInkFrac` /
 *   `dimInkFrac` spacing pins from the settled ink extents (bright runs read
 *   130/413/460/56 native ≈ 4/13/15/2 chars; dim 429/397/331/447 ≈ 22/21/17/24).
 * - The title band carries FOUR ink runs (settled white/green component
 *   scan): x 692–951, 978–1258, 1288–1735, and the green tail 1758–1866 —
 *   a common cap band y 139–215.5 (76.5px caps). Glyph-cell segmentation
 *   counts ≈4/5/8/2 glyphs; the recorded face is condensed, so every run
 *   pins spacing-only via `compareBadgeTitleTokens` (glyphs never squeeze).
 *   The words are not transcribable at native resolution (three independent
 *   matcher passes failed this session); the strings are best-effort
 *   legible-in-spirit at the measured glyph counts — geometry is exact.
 * - Reveal (onsets.json + f15 dumps, 15fps): the badge core fades in at
 *   t≈0.600 (red event 12811px) and reaches full orange by ≈0.667 (orange
 *   13004px); the halo/leaders trail to ≈0.733. Four text waves then
 *   alternate left/right: left-top ≈1.00, right-top ≈1.733, left-bottom
 *   ≈3.00, right-bottom ≈4.40 — each wave carries its plate, icon, and both
 *   text lines together (~320ms fade).
 *
 * All functions here are pure and deterministic: same inputs produce
 * byte-identical output, and nothing touches the DOM (SSR-safe build).
 */

/** A resolved rectangle in stage units (1920×1080 by default). */
export interface BadgeRect {
  x: number
  y: number
  w: number
  h: number
}

/** A resolved circle in stage units. */
export interface BadgeCircle {
  cx: number
  cy: number
  r: number
}

/** A resolved line segment in stage units. */
export interface BadgeSegment {
  x1: number
  y1: number
  x2: number
  y2: number
}

/** One measured text row: ink start, ink band top, band height, baseline. */
export interface BadgeLineBox {
  /** Ink left edge (stage units). */
  x: number
  /** Top of the ink band — cap band for bright rows, x-height band for dim rows. */
  topY: number
  /** Ink band height (stage units). */
  bandHeight: number
  /** Text baseline (stage units) — the ink band's bottom edge. */
  baseline: number
}

/** Which of the four plate rows a piece of content belongs to. */
export type BadgeRowId = 'leftTop' | 'rightTop' | 'leftBottom' | 'rightBottom'

/** A plate row with its resolved geometry and reveal click. */
export interface BadgeRowLayout {
  id: BadgeRowId
  /** 1-based Slidev click that reveals this row (badge itself is click 1). */
  click: number
  /** The near-black plate rectangle. */
  plate: BadgeRect
  /** Icon glyph box inside the plate (content = icons.ts registry key). */
  icon: BadgeRect
  /** Bright white headline row. */
  bright: BadgeLineBox
  /** Dim gray detail row. */
  dim: BadgeLineBox
}

/** Resolved layout for the whole composition on one canvas. */
export interface CompareBadgeLayout {
  /** Four rows in reveal order: leftTop → rightTop → leftBottom → rightBottom. */
  rows: BadgeRowLayout[]
  /**
   * Dark red-brown radial glow behind the core (the settled "red rim"):
   * center = core center, `r` = glow radius, peak at the core edge
   * (HALO_PEAK_FRAC) fading to transparent at `r`.
   */
  halo: BadgeCircle
  /** Orange rounded-square core. */
  core: BadgeRect & { corner: number }
  /** Dark glyph box centered in the core (content = optional icons.ts key). */
  glyph: BadgeRect
  /** Dim leader lines from the glow to the plates' inner edges (three in
   *  the settled frame — no lower-right stroke). */
  leaders: BadgeSegment[]
  viewBox: { width: number; height: number }
}

export interface CompareBadgeOptions {
  /** ViewBox width in user units. Default 1920. */
  width?: number
  /** ViewBox height in user units. Default 1080. */
  height?: number
}

/**
 * Measured constants in NATIVE settled-frame pixels (2560×1440) — the numbers
 * cite the frame, not the stage; `compareBadgeLayout` scales them to the
 * requested canvas. Plate/icon/leader edges come from settled-frame luma
 * scanlines (6–40 plate band, this session); the core box is report.json's
 * `orange[0]` bbox; the text bands are the settled white component +
 * per-row ink profiles.
 */
