const NATIVE = { width: 2560, height: 1440 } as const

/**
 * Settled-fill family constants (median samples on the seg12 settled frame).
 * Ambient tones are family constants, not palette roles — the badge core is
 * the exception: it rides `palette.accent` through the `orangeSpine` preset,
 * whose accent IS this exact color.
 */
export const PLATE_FILL = '#12131a'
/**
 * Plate edge treatment (stage px): the settled frame frames each plate with
 * 2-native-px horizontal accent lines top and bottom (edge median
 * rgb(45,46,55)) plus a soft compression skirt fading out over ~8px. The
 * left/right edges sit at or below fill luma and carry no line, so the
 * frame renders lines, not a full stroke. The outer skirts are teal-tinted
 * in the frame (rgb(2,41,41) above the top line, rgb(9,30,47) below the
 * bottom) — ambient from the surrounding composition — so each edge paints
 * core, neutral inner fade, then tinted outer fade.
 */
export const PLATE_EDGE = {
  coreColor: '#2d2e37',
  coreHeight: 1.75,
  innerFadeHeight: 2.5,
  outerFadeHeight: 9,
  topOuterColor: '#022929',
  bottomOuterColor: '#091e2f',
} as const
export const HALO_FILL = '#401507'
/**
 * Fraction of the glow radius where the settled rim peaks — the core edge
 * sits at r≈128 of the r≈190 native glow.
 */
export const HALO_PEAK_FRAC = 128 / 190
export const LEADER_STROKE = '#bb5323'
/** Exact settled core sample — the research brief pins this hex verbatim. */
export const CORE_FILL = '#f85721'

/** One traced ink path: even-odd subpath data plus its sampled fill. */
export interface InkPath {
  /** SVG path data in stage units (M/L/Z subpaths, even-odd fill). */
  d: string
  /** Sampled settled ink color. */
  fill: string
  /**
   * Paint opacity for antialiasing-skirt passes (default 1): each text/icon
   * region paints a low-alpha skirt contour reconstructed from the
   * sub-half-ink threshold, then the opaque core — together they model the
   * recording's AA ramp, which a single mid-threshold trace clips thin.
   * Contours are traced at native 2560×1440 and scaled to stage.
   */
  opacity?: number
}

/** Traced settled ink for one plate row (text runs + icon glyph). */
export interface Seg12RowInk {
  bright: InkPath[]
  dim: InkPath[]
  icon: InkPath[]
}

